namespace Encapsulatie;

// Exercise 05: a bank account that protects its own balance.
// The tests in BankAccountTests.cs must go green.
public class BankAccount
{
    public string Owner { get; }
    public decimal Balance { get; private set; }

    public BankAccount(string owner, decimal openingBalance)
    {
        Owner = owner;
        Balance = openingBalance;
    }

    public void Deposit(decimal amount)
    {
        if (amount <= 0) throw new ArgumentOutOfRangeException(nameof(amount));
        Balance += amount;
    }

    // TODO: Withdraw(decimal amount)
    //  - amount must be positive, otherwise ArgumentOutOfRangeException
    //  - the balance may never go below zero: then InvalidOperationException
    //  - otherwise lower the balance by amount
}

