namespace Encapsulatie.Tests;

public class BankAccountTests
{
    [Test] public void Withdraw_negative_throws() => Assert.Throws<ArgumentOutOfRangeException>(() => new BankAccount("a", 10).Withdraw(-1));
    [Test] public void Withdraw_too_much_throws() => Assert.Throws<InvalidOperationException>(() => new BankAccount("a", 10).Withdraw(11));
    [Test] public void Withdraw_lowers_balance() { var b = new BankAccount("a", 10); b.Withdraw(4); Assert.That(b.Balance, Is.EqualTo(6)); }
}

